'use strict';
// Baileys PALSU untuk uji proses jembatan (tests/test_wa_bridge_process.py). Bukan WhatsApp sungguhan:
// - pesan masuk disuntikkan lewat berkas $FAKE_WA_DIR/inject.jsonl (satu JSON {messages,type} per baris)
// - pesan keluar dicatat ke $FAKE_WA_DIR/sent.jsonl; unduhan media ke download.log
// - $FAKE_WA_FAIL = daftar JID (dipisah koma) yang ditolak saat dikirimi pesan
const fs = require('fs');
const path = require('path');

const dir = process.env.FAKE_WA_DIR;
const failing = new Set((process.env.FAKE_WA_FAIL || '').split(',').filter(Boolean));
const handlers = {};
let counter = 0;
let sock = null;

const append = (name, obj) => fs.appendFileSync(path.join(dir, name), JSON.stringify(obj) + '\n');
const fire = (name, payload) => (handlers[name] || []).forEach((fn) => fn(payload));

function makeWASocket() {
  sock = {
    user: { id: `${process.env.FAKE_WA_SELF || '6283125645146'}:7@s.whatsapp.net`,
      lid: `${process.env.FAKE_WA_LID || '99887766554433'}:7@lid` },
    ev: { on(name, fn) { (handlers[name] = handlers[name] || []).push(fn); } },
    async sendMessage(jid, body) {
      if (failing.has(jid)) throw new Error('ditolak server: ' + jid);
      append('sent.jsonl', { jid, text: body.text, document: Boolean(body.document) });
      return { key: { id: 'OUT' + (++counter) } };
    },
    end() {},
    async logout() {},
    updateMediaMessage() {},
  };
  setTimeout(() => fire('connection.update', { connection: 'open' }), 30);
  let offset = 0;
  setInterval(() => {
    const file = path.join(dir, 'inject.jsonl');
    if (!fs.existsSync(file)) return;
    const data = fs.readFileSync(file, 'utf8');
    const end = data.lastIndexOf('\n') + 1;
    const lines = data.slice(offset, end).split('\n').filter(Boolean);
    offset = end;
    for (const line of lines) fire('messages.upsert', JSON.parse(line));
  }, 20);
  return sock;
}

module.exports = {
  default: makeWASocket,
  useMultiFileAuthState: async () => ({ state: {}, saveCreds() {} }),
  downloadMediaMessage: async (m) => {
    append('download.log', { id: m.key && m.key.id });
    return Buffer.from('ISI-BERKAS-PALSU');
  },
};
